package markus.wieland.pushygame.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import androidx.annotation.RawRes
import kotlinx.coroutines.flow.StateFlow
import markus.wieland.pushygame.R

/** Every sound effect. The WAVs in `res/raw` are generated by `tools/sounds/make_sounds.py`. */
enum class Sound(@param:RawRes val res: Int, val volume: Float = 1f) {
    STEP(R.raw.sfx_step, 0.35f),
    PUSH(R.raw.sfx_push, 0.8f),
    BUMP(R.raw.sfx_bump, 0.6f),
    CLICK(R.raw.sfx_click, 0.7f),
    SPLASH(R.raw.sfx_splash),
    DROP(R.raw.sfx_drop, 0.8f),
    PICKUP(R.raw.sfx_pickup, 0.7f),
    EXPLOSION(R.raw.sfx_explosion),
    TELEPORT(R.raw.sfx_teleport, 0.8f),
    JUMP(R.raw.sfx_jump, 0.8f),
    SHOT(R.raw.sfx_shot, 0.8f),
    HIT(R.raw.sfx_hit, 0.7f),
    SAIL(R.raw.sfx_sail, 0.8f),
    WIN(R.raw.sfx_win, 0.9f),
    ICE_MELT(R.raw.sfx_ice_melt, 0.8f),
    SPIKES_DOWN(R.raw.sfx_spikes_down, 0.7f),
    SPIKES_UP(R.raw.sfx_spikes_up, 0.7f),
    DOOR_OPEN(R.raw.sfx_door_open, 0.8f),
    DOOR_CLOSE(R.raw.sfx_door_close, 0.8f),
    REVEAL(R.raw.sfx_reveal, 0.7f),
    GROW(R.raw.sfx_grow, 0.8f),
    PLANT(R.raw.sfx_plant, 0.6f),
    LAMP_ON(R.raw.sfx_lamp_on, 0.6f),
}

/** Plays [Sound]s through a [SoundPool] while [enabled] is true. */
class SoundEffects(context: Context, private val enabled: StateFlow<Boolean>) {
    private val pool = SoundPool.Builder()
        .setMaxStreams(MAX_STREAMS)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build(),
        )
        .build()

    private val ids = Sound.entries.associateWith { pool.load(context, it.res, 1) }

    fun play(sound: Sound) {
        if (!enabled.value) return
        val id = ids[sound] ?: return
        pool.play(id, sound.volume, sound.volume, 1, 0, 1f)
    }

    private companion object {
        const val MAX_STREAMS = 6
    }
}
